-- Sarel's answers to hardcoded-assumptions audit Q3 and Q5 (2026-10-17).
-- Evidence: docs/specs/Discipline-Taxonomy-Findings.md,
-- docs/specs/Hardcoded-Assumptions-Audit.md §9.
--
-- 1. discipline_categories - Tender Tool's OWN discipline / category list.
--    Sarel: "There is no standard list. We will have to build it as we get
--    new tenders into the system ... CIDB is only a small portion of the
--    tenders ... Let's rather build our own list ... it's a list that we're
--    gonna have to maintain and build." So it is a lookup TABLE, not a CHECK
--    list: a new category is an INSERT (engine/discovery/taxonomy.py add, or
--    SQL as the service role) and needs no migration. Same idea as 0036,
--    which opened experience_items.disciplines to any slug.
--
--    Two levels: a row with parent_slug null is a discipline GROUP; children
--    are the specific disciplines a tender is sorted into. The seven keyword
--    buckets Tender Tool started with (roads_civil, water, buildings,
--    electrical_mechanical, it_telecoms, professional_services,
--    security_facilities) are kept as group slugs, so every experience tag,
--    price_sector value and discovered_opportunities.categories value
--    written before this migration is still a valid category.
--
--    Seed (below): 19 groups / 93 disciplines built from 2 211 live eTenders
--    opportunities (2026-10-17) + 400 OCDS releases + the 11 general and 6
--    SANRAL samples, cross-referenced to eTenders.gov.za's own 91-entry
--    category dropdown (etenders_categories), Leads 2 Business's 17 tender
--    categories (l2b_categories) and, for works, CIDB's classes of
--    construction works (cidb_classes) - CIDB as a cross-reference only, not
--    the taxonomy (it covers works, not the services and goods most tenders
--    are). The same list is config/discipline_taxonomy.json (offline
--    fallback; taxonomy.py sync pushes it here).
--
--    keywords / exclude_keywords drive engine/discovery/assess_tender.py
--    categorize(): whole-word phrases, trailing * = any ending, "a & b" =
--    both present, an exclude starting with ! vetoes the category.
--
--    Read by every signed-in user (suggestions on the Experience Library and
--    the pricing form); written only by the service role (no client write
--    policy) - it is shared reference data, like tender_roles (0016).
--
-- 2. tender_packs.price_sector (0034) was CHECK-constrained to the 7 bucket
--    keys. It now references discipline_categories, so any category on the
--    list (and any added later) is a valid sector - again no migration per
--    new category.
--
-- 3. people: SACNASP and SAGC registrations (Q5). Sarel: "We can
--    accommodate that into the structure, but don't specifically ask for it
--    unless the tender requires it." Same shape as ECSA / SACPCMP (0001 +
--    0035): category (free text, like ecsa_level), number, and the
--    lapse/renewal date (expiry, as on the certificate - never computed).
--    Nullable, no default: the People page shows them only when the person
--    already holds one or a tender on the system asks for that body
--    (app/lib/personCredentials.ts registrationsAskedFor); the compliance
--    check reads them only for a position whose requirement names the body
--    (Engineering Geologist -> SACNASP, Surveyor -> SAGC). The expiry joins
--    engine/compliance/watch_deadlines.py TRACKED_PERSON_EXPIRY_FIELDS - the
--    same reminder mechanism as ECSA/SACPCMP. Covered by 0001's "people:
--    tenant isolation" policy; no new policy.

create table discipline_categories (
  slug text primary key check (slug ~ '^[a-z][a-z0-9_]{0,62}$'),
  label text not null check (length(trim(label)) > 0),
  parent_slug text references discipline_categories(slug) on update cascade on delete restrict,
  sort_order integer not null default 1000,
  keywords text[] not null default '{}',
  exclude_keywords text[] not null default '{}',
  etenders_categories text[] not null default '{}',
  l2b_categories text[] not null default '{}',
  cidb_classes text[] not null default '{}',
  active boolean not null default true,
  added_from text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (parent_slug is null or parent_slug <> slug)
);

comment on table discipline_categories is
  'Tender Tool''s own, maintained discipline/category list (Sarel 2026-10-17, audit Q3). Add a category by inserting a row - no migration. parent_slug null = group. Seeded from real tenders: docs/specs/Discipline-Taxonomy-Findings.md.';
comment on column discipline_categories.keywords is
  'Phrases assess_tender.categorize() matches in a tender title/description: whole words, trailing * = any ending, "a & b" = both present.';
comment on column discipline_categories.exclude_keywords is
  'Phrases cut out of the text before this category is tried (buyer names like "road accident fund"); one starting with ! vetoes the category when present.';
comment on column discipline_categories.etenders_categories is
  'eTenders.gov.za category dropdown entries this category corresponds to (cross-reference, not used for matching).';
comment on column discipline_categories.active is
  'false = retired: no longer offered or matched, kept so stored tags still have a label.';

-- Two levels only: a parent must itself be a group.
create or replace function discipline_categories_two_levels()
returns trigger
language plpgsql
as $$
begin
  if new.parent_slug is not null and exists (
    select 1 from discipline_categories p where p.slug = new.parent_slug and p.parent_slug is not null
  ) then
    raise exception 'discipline_categories: parent % is itself a child - two levels only', new.parent_slug;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger discipline_categories_two_levels
  before insert or update on discipline_categories
  for each row execute function discipline_categories_two_levels();

alter table discipline_categories enable row level security;
create policy "discipline_categories readable by authenticated users" on discipline_categories
  for select to authenticated using (true);

