-- 2. price_sector: any category on the list.
alter table tender_packs drop constraint if exists tender_packs_price_sector_check;
alter table tender_packs
  add constraint tender_packs_price_sector_fkey
  foreign key (price_sector) references discipline_categories(slug) on update cascade on delete set null;
comment on column tender_packs.price_sector is
  'Sector/discipline for the pricing history: a discipline_categories slug (0040; was a CHECK list of 7). Prefilled from Discovery categories, editable.';

comment on column experience_items.disciplines is
  'Discipline tags. Suggested set = discipline_categories (0040; groups + disciplines, what discovered tenders are categorised into); companies may still add their own lower-case slug tags (0036). Not a closed list.';

-- 3. SACNASP / SAGC registrations - optional, shown only when relevant.
alter table people
  add column sacnasp_category text,
  add column sacnasp_number text,
  add column sacnasp_expiry date,
  add column sagc_category text,
  add column sagc_number text,
  add column sagc_expiry date;

comment on column people.sacnasp_category is
  'SACNASP (SA Council for Natural Scientific Professions) category as on the certificate, e.g. Pr.Sci.Nat / Cand.Sci.Nat / Cert.Sci.Nat. Asked for only when a tender requires it (e.g. SANRAL C3.1.11 Engineering Geologist: Pr Sci.Nat). Null = not recorded.';
comment on column people.sacnasp_number is 'SACNASP registration number. Null = not recorded.';
comment on column people.sacnasp_expiry is
  'Date the SACNASP registration lapses / is next due for renewal, as on the certificate or renewal notice. Null = not recorded (never treated as expired). Tracked by watch_deadlines.py.';
comment on column people.sagc_category is
  'SAGC (SA Geomatics Council) category as on the certificate, e.g. Professional Land Surveyor / Professional Surveyor / Geomatics Technologist / Geomatics Technician. Asked for only when a tender requires it (e.g. SANRAL C3.1.11 Surveyor). Null = not recorded.';
comment on column people.sagc_number is 'SAGC registration number. Null = not recorded.';
comment on column people.sagc_expiry is
  'Date the SAGC registration lapses / is next due for renewal, as on the certificate or renewal notice. Null = not recorded. Tracked by watch_deadlines.py.';
